'use client';
// Scroll-scrubbed image sequence (Estúdio page) — original module 85510. Olwtelet Productions: 50 frames of the mark
// turning in the light (public/assets/about/sequence, generated by scripts/brand/build-brand-assets.mjs).
// - 50 webp frames (1920×1080) preloaded as Image objects on mount.
// - Layout b(): canvas.width = container.clientWidth, height = 9/16 · width (square when screen.width < 600);
//   container marginTop = ceil(-previousElementSibling.offsetHeight - 0.25 · height) (pulls the canvas up over the
//   last slice); draw size = canvas size only when width > 600 && height > 338, else stays 600×338 (quirk kept).
//   Re-run on window resize, debounced 100 ms.
// - Scroll C() (window `scroll`): when rect.top < screen.height - n (n = 40 on mobile-UA portrait, else 120):
//   frame = ceil((1 - ref / 2 / height) · 55) with ref = rect.bottom (rect.top on mobile portrait); frames ≤ 0 or ≥ 50
//   are ignored. Nothing is drawn until the first such scroll changes the frame (or the size changes).
// DIVERGENCE (docs/implementation/about.md D9): the original keeps the frame index in useState and draws in a passive
// effect ([drawSize, frame, frames]). Here the index lives in a ref and the scroll handler draws directly when it
// changes (same frame, same draw rect, same "only on change" rule). Reason: one React commit per scroll event (an
// InputContinuous lane) on the dev server repeatedly interrupted a slower Default-lane render; React 19.2 counts each
// such commit as a nested update (`261930 & lanes && 42 & pendingLanes`, the same check is in the original's React)
// and threw "Maximum update depth exceeded" after 50 of them, unmounting the page (MEASURED, scripts/about/errors2.mjs).
import { useCallback, useEffect, useRef, useState } from 'react';
import { mediaUrl } from '@/lib/media';
import s from './awardsImageSequence.module.css';

const BASE = '/assets/about/sequence';
const PULL_UP_OVER_PREVIOUS_SLICE = false;

/** module 66754 `Fr` */
const isMobileUA = () => /Mobi|Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent);

export default function AwardsImageSequence() {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [frames, setFrames] = useState<HTMLImageElement[]>([]);
  const [marginTop, setMarginTop] = useState<number | null>(null);
  const frameRef = useRef(0);
  const [drawSize, setDrawSize] = useState({ width: 600, height: 338 });
  const framesRef = useRef<HTMLImageElement[]>(frames);
  framesRef.current = frames;
  const drawSizeRef = useRef(drawSize);
  drawSizeRef.current = drawSize;
  const debounce = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  /** original passive effect body: clear + drawImage(frames[frame], 0, 0, drawSize) */
  const draw = useCallback(() => {
    const c = canvasRef.current;
    const imgs = framesRef.current;
    if (!c || imgs.length < 1) return;
    const ctx = c.getContext('2d')!;
    ctx.clearRect(0, 0, c.width, c.height);
    ctx.drawImage(imgs[frameRef.current], 0, 0, drawSizeRef.current.width, drawSizeRef.current.height);
  }, []);

  const preload = useCallback(() => {
    setFrames([]);
    for (let i = 1; i <= 50; i++) {
      const img = new Image();
      img.src = mediaUrl(`${BASE}/olwtelet-mark-${i.toString().padStart(4, '0')}.webp`);
      img.alt = '';
      setFrames((f) => [...f, img]);
    }
  }, []);

  useEffect(() => {
    const onScroll = () => {
      if (!canvasRef.current) return;
      const { top, bottom, height } = canvasRef.current.getBoundingClientRect();
      const mobilePortrait = isMobileUA() && window.screen.height > window.screen.width;
      const n = mobilePortrait ? 40 : 120;
      if (top < window.screen.height - n) {
        let ref = bottom;
        if (mobilePortrait) ref = top;
        const f = Math.ceil((1 - ref / 2 / height) * 55.00000000000001);
        if (f <= 0 || f >= 50) return;
        // setState bail-out equivalent: only a changed frame re-draws
        if (f !== frameRef.current) {
          frameRef.current = f;
          draw();
        }
      }
    };
    const layout = () => {
      if (!containerRef.current || !canvasRef.current) return;
      const w = containerRef.current.clientWidth;
      let h = (9 / 16) * w;
      if (window.screen.width < 600) h = w;
      // Olwtelet: no pull-up over the previous slice (the replica's trophies overlapped the "Recognition" text; here the
      // previous slices are the location and contact blocks, which must stay readable), so marginTop stays unset.
      if (PULL_UP_OVER_PREVIOUS_SLICE) {
        const prev = containerRef.current.previousElementSibling as HTMLElement | null;
        if (prev) setMarginTop(Math.ceil(-prev.offsetHeight - 0.25 * h));
      }
      const ctx = canvasRef.current.getContext('2d')!;
      ctx.canvas.width = w;
      ctx.canvas.height = h;
      if (w > 600 && h > 338) setDrawSize({ width: w, height: h });
    };
    const onResize = () => {
      clearTimeout(debounce.current);
      debounce.current = setTimeout(layout, 100);
    };
    preload();
    layout();
    window.addEventListener('scroll', onScroll);
    window.addEventListener('resize', onResize);
    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onResize);
      containerRef.current = null;
      canvasRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    draw();
  }, [drawSize, frames, draw]);

  return (
    <div ref={containerRef} className={s.Container} style={{ marginTop: marginTop || undefined }}>
      <canvas ref={canvasRef} />
    </div>
  );
}
